// src/types/contracts.ts
// Shared API Request & Response Contracts across P1, P2, and P3.
// For DB table rows, import from `./database.types` (auto-generated by Supabase CLI).

export type ConfidenceLevel = "high" | "amber";
export type StockSource = "simulated" | "pharmacy_reported" | "confirmed";
export type PlanMode =
  | "cheapest"
  | "nearest"
  | "generic_saver"
  | "fewest_stops"
  | "best_balanced";

export type VerificationStatus =
  | "pending"
  | "verified"
  | "original_required"
  | "rejected";

export type ReservationItemStatus =
  | "pending"
  | "confirmed"
  | "declined"
  | "substitute_suggested"
  | "substitute_approved"
  | "substitute_rejected";

export type MedicineMatchStatus =
  | "exact"
  | "alias"
  | "auto_matched"     // >= 90% similarity se auto-replace hua
  | "needs_selection"  // < 90% similarity -> UI dropdown options dikhayega
  | "manual_required"; // koi close match nahi -> user khud enter karega

export interface MedicineSuggestion {
  medicine_id: string;
  brand_name: string;
  composition_display: string;
  similarity: number; // e.g., 0.85 means 85% match
}

// =========================================================
// CONTRACT 1: P1 -> P2 (/api/extract & /api/safety)
// =========================================================

export interface ExtractRequest {
  /** Private bucket path: `${user.id}/${fileName}` (never POST raw >4MB files) */
  storage_path: string;
  image_hash?: string;
}

export interface SafetyFlag {
  severity: "red" | "amber";
  category: "allergy" | "condition" | "interaction" | "nti_lock" | "schedule_h";
  message: string;
  disclaimer: string;
}

export interface ExtractedMedicineItem {
  temp_id: string;
  raw_text: string;
  matched_medicine_id: string | null;
  brand_name: string;
  composition_key: string | null;
  composition_display: string | null;
  dose: string | null;
  duration: string | null;
  confidence: ConfidenceLevel; // "amber" => patient must verify on review screen
  is_nti: boolean;             // true => locks allow_alternative to false
  is_schedule_h: boolean;      // true => requires Rx / pharmacist verification
  allow_alternative: boolean;  // "Alternative chalega" vs "Sirf yahi brand"
  safety_flags: SafetyFlag[];  // empty [] in Phase 1, populated in Phase 2
  match_status?: MedicineMatchStatus;
  suggestions?: MedicineSuggestion[];
}

export interface ExtractResponse {
  prescription_id: string;
  from_demo_cache: boolean;
  items: ExtractedMedicineItem[];
  trust_checks: {
    date_valid: boolean | null;
    patient_name_match: boolean | null;
    is_duplicate: boolean;
  };
}

export interface ConfirmedMedicine {
  medicine_id: string;
  brand_name: string;
  composition_key: string;
  strength: string | null;
  dosage: string | null;
  mrp: number;
  selected_alternative_id: string | null;
  selected_alternative_brand_name?: string | null;
  selected_alternative_mrp?: number | null;
  is_nti: boolean;
  is_schedule_h?: boolean;
}

/**
 * Transforms confirmed review medicines into downstream P3 PlanRequest items.
 */
export function confirmedMedicinesToPlanItems(
  medicines: ConfirmedMedicine[]
): PlanRequest["items"] {
  return medicines.map((m) => ({
    medicine_id: m.selected_alternative_id || m.medicine_id,
    composition_key: m.composition_key,
    allow_alternative: !m.is_nti && Boolean(m.selected_alternative_id),
    is_nti: m.is_nti,
  }));
}

// =========================================================
// CONTRACT 2: P1 -> P3 (/api/plans)
// =========================================================

export interface PlanRequest {
  user_lat: number;
  user_lng: number;
  items: {
    medicine_id: string;
    composition_key: string;
    allow_alternative: boolean;
    is_nti: boolean;
  }[];
}

export interface QuotedItem {
  requested_medicine_id: string;
  quoted_medicine_id: string;
  quoted_brand_name: string;
  is_alternative: boolean;
  is_jan_aushadhi: boolean;
  mrp: number;
  final_price: number;
  stock_source: StockSource;
}

export interface PlanStop {
  shop_id: string;
  shop_name: string;
  shop_type: "chemist" | "jan_aushadhi";
  address: string;
  lat: number;
  lng: number;
  distance_km: number;
  reliability_score: number;
  items: QuotedItem[];
  stop_subtotal: number;
}

export interface PharmacyPlan {
  mode: PlanMode;
  total_mrp: number;
  final_price: number;
  savings: number;
  total_distance_km: number;
  stops: PlanStop[]; // capped at max 2 stops for fast exact optimization
}

export interface PlanResponse {
  plans: PharmacyPlan[];
  unmatched_medicine_ids: string[];
}

// =========================================================
// CONTRACT 3: P1 <-> P3 (/api/reservations)
// =========================================================

export interface CreateReservationRequest {
  shop_id: string;
  prescription_id?: string | null;
  plan_mode: PlanMode;
  items: {
    requested_medicine_id: string;
    allow_alternative: boolean;
  }[];
}

export interface PharmacistDecisionRequest {
  reservation_id: string;
  verification_status?: VerificationStatus;
  pharmacist_note?: string;
  item_updates?: {
    reservation_item_id: string;
    item_status: ReservationItemStatus;
    suggested_medicine_id?: string | null;
    final_price?: number | null;
  }[];
}